1	import type { globalSettings } from '../../cli/globalSettings.ts';
2	import type { UniversalStore } from '../universal-store/index.ts';
3	import type { StoreOptions } from '../universal-store/types.ts';
4	import { initialState } from './checklistData.state.ts';
5	
6	/** ChecklistState is the persisted state, which may be incomplete */
7	export type ChecklistState = NonNullable<
8	  Awaited<ReturnType<typeof globalSettings>>['value']['checklist']
9	>;
10	
11	/** Store uses initialState to ensure all items are present */
12	export type StoreState = Required<Omit<ChecklistState, 'items'>> & {
13	  items: NonNullable<Required<ChecklistState['items']>>;
14	  loaded?: boolean;
15	  /** True when the user opted into AI during `storybook init`. Set by the server from the event cache. */
16	  aiOptIn?: boolean;
17	};
18	
19	export type ItemId = keyof StoreState['items'];
20	export type ItemState = StoreState['items'][keyof StoreState['items']];
21	
22	export type StoreEvent =
23	  | { type: 'accept'; payload: ItemId }
24	  | { type: 'done'; payload: ItemId }
25	  | { type: 'skip'; payload: ItemId }
26	  | { type: 'reset'; payload: ItemId }
27	  | { type: 'mute'; payload: Array<ItemId> }
28	  | { type: 'disable'; payload: boolean };
29	
30	export const UNIVERSAL_CHECKLIST_STORE_OPTIONS: StoreOptions<StoreState> = {
31	  id: 'storybook/checklist',
32	  initialState,
33	} as const;
34	
35	export type ChecklistStoreEnvironment = 'server' | 'manager' | 'preview';
36	
37	export const createChecklistStore = (
38	  universalChecklistStore: UniversalStore<StoreState, StoreEvent>
39	) => ({
40	  getValue: (id: ItemId) =>
41	    universalChecklistStore.getState().items[id] ?? { status: 'open', mutedAt: undefined },
42	  accept: (id: ItemId) => {
43	    universalChecklistStore.setState((state) => ({
44	      ...state,
45	      items: { ...state.items, [id]: { ...state.items[id], status: 'accepted' } },
46	    }));
47	  },
48	  done: (id: ItemId) => {
49	    universalChecklistStore.setState((state) => ({
50	      ...state,
51	      items: { ...state.items, [id]: { ...state.items[id], status: 'done' } },
52	    }));
53	  },
54	  skip: (id: ItemId) => {
55	    universalChecklistStore.setState((state) => ({
56	      ...state,
57	      items: { ...state.items, [id]: { ...state.items[id], status: 'skipped' } },
58	    }));
59	  },
60	  reset: (id: ItemId) => {
61	    universalChecklistStore.setState((state) => ({
62	      ...state,
63	      items: { ...state.items, [id]: { ...state.items[id], status: 'open' } },
64	    }));
65	  },
66	  mute: (itemIds: Array<ItemId>) => {
67	    universalChecklistStore.setState((state) => ({
68	      ...state,
69	      items: itemIds.reduce(
70	        (acc, id) => ({ ...acc, [id]: { ...state.items[id], mutedAt: Date.now() } }),
71	        state.items
72	      ),
73	    }));
74	  },
75	  disable: (value: boolean) => {
76	    universalChecklistStore.setState((state) => ({
77	      ...state,
78	      widget: { ...state.widget, disable: value },
79	      items: Object.entries(state.items).reduce(
80	        (acc, [id, value]) => ({ ...acc, [id]: { ...value, mutedAt: undefined } }),
81	        state.items
82	      ),
83	    }));
84	  },
85	});
