1	import type { IndexEntry } from 'storybook/internal/types';
2	
3	/**
4	 * Determines whether a story index entry was authored by the `sb ai setup` flow.
5	 * Currently checks title prefix. When we migrate to a tag-based approach,
6	 * swap this to check for the tag instead — this is the single swap point.
7	 */
8	export function isStoryCreatedByAISetup(entry: IndexEntry): boolean {
9	  return entry.type === 'story' && (entry.tags?.includes('ai-generated') ?? false);
