19	export function initAIAnalyticsChannel(
20	  channel: Channel,
21	  options: Options,
22	  getStoryIndexGeneratorPromise?: () => Promise<StoryIndexGenerator> | undefined
23	) {
24	  /** Send analytics about the ai setup workflow when requested*/
25	  channel.on(AI_SETUP_ANALYTICS_REQUEST, async () => {
26	    const stats: {
27	      fileCount?: number;
28	      storyCount?: number;
29	      testRunDuration?: number;
30	    } = {};
31	
32	    try {
33	      const lastEvents = await getLastEvents();
34	      const lastAISetup = lastEvents?.['ai-setup'];
35	      const lastSetupStoryScoringRun = lastEvents?.['ai-setup-final-scoring'];
36	
37	      // Only run if sb ai setup has been called
38	      if (!lastAISetup) {
39	        return;
40	      }
41	
42	      // Already ran once for this project — never run again
43	      if (lastSetupStoryScoringRun) {
44	        return;
45	      }
46	
47	      const metadata = await getStorybookMetadata(options.configDir);
48	      const isReactStorybook = metadata?.renderer?.includes('@storybook/react');
49	      const hasVitestAddon =
50	        !!metadata?.addons &&
51	        Object.keys(metadata.addons).some((addonKey) =>
52	          addonKey.includes('@storybook/addon-vitest')
53	        );
54	
55	      // For now this is gated by React + Vitest
56	      if (!isReactStorybook || !hasVitestAddon) {
57	        return;
58	      }
59	
60	      // Wait for any running tests to finish before launching scoring, so we don't
61	      // disturb end user activities.
62	      const isIdle = await waitForIdleVitest();
63	      if (!isIdle) {
64	        logger.debug('AI_SETUP_ANALYTICS_REQUEST timed out waiting for vitest to be available.');
65	        return;
66	      }
67	
68	      // Fetch AI-generated stories and score them with the ghost stories metrics, if any are found.
69	      const generatorPromise = getStoryIndexGeneratorPromise?.();
70	      if (!generatorPromise) {
71	        logger.debug(
72	          'AI_SETUP_ANALYTICS_REQUEST could not proceed as the index generator is not ready.'
73	        );
74	        return;
75	      }
76	
77	      const generator = await generatorPromise;
78	      const indexAndStats = await generator.getIndexAndStats();
79	      if (!indexAndStats) {
80	        logger.debug('AI_SETUP_ANALYTICS_REQUEST could not proceed as the index is not ready.');
81	        return;
82	      }
83	
84	      const aiStoryFiles = new Set<string>();
85	      let aiStoryCount = 0;
86	      for (const entry of Object.values(indexAndStats.storyIndex.entries)) {
87	        if (isStoryCreatedByAISetup(entry)) {
88	          aiStoryFiles.add(entry.importPath);
89	          aiStoryCount++;
90	        }
91	      }
92	
93	      if (aiStoryFiles.size > 0) {
94	        const aiTestRunResult = await runStoryTests([...aiStoryFiles]);
95	        telemetry('ai-setup-final-scoring', {
96	          stats: {
97	            fileCount: aiStoryFiles.size,
98	            storyCount: aiStoryCount,
99	            testRunDuration: aiTestRunResult.duration,
100	          },
101	          results: aiTestRunResult.summary,
102	          ...(aiTestRunResult.runError ? { runError: aiTestRunResult.runError } : {}),
103	        });
104	      } else {
105	        telemetry('ai-setup-final-scoring', {
106	          stats: {
107	            fileCount: 0,
108	            storyCount: 0,
109	            testRunDuration: 0,
110	          },
111	          runError: 'No stories found that were generated by ai setup',
112	        });
113	      }
114	    } catch {
115	      telemetry('ai-setup-final-scoring', {
116	        stats,
117	        runError: 'Unknown error during AI story scoring',
118	      });
119	    } finally {
120	      // we don't currently do anything with this, but will be useful in the future
121	      channel.emit(AI_SETUP_ANALYTICS_RESPONSE);
122	    }
123	  });
124	
125	  return channel;
126	}
