/**
 * Shape of the AI flag entries persisted in the shared cache. `configDir` is the
 * absolute path of the project the flag was written for, so a single cache can
 * distinguish individual projects within a monorepo.
 */
type AiFlagCacheEntry = { timestamp: number; configDir: string };

/**
 * Whether the user opted into AI during `storybook init` for the given project.
 * Reads the 'ai-init-opt-in' cache entry and returns true only when its
 * `configDir` matches the absolute path of the provided `configDir`.
 */
export async function hasAiInitOptIn(configDir: string): Promise<boolean> {
  const entry = (await cache.get('ai-init-opt-in')) as AiFlagCacheEntry | undefined;
  if (!entry?.configDir) {
    return false;
  }
  return entry.configDir === resolve(configDir);
}

/**
 * Whether `storybook ai setup` has run for the given project. Reads the
 * 'ai-setup-ran' cache entry and returns true only when its `configDir` matches
 * the absolute path of the provided `configDir`. Relative paths are resolved
 * against the current working directory.
 */
export async function hasAiSetupRun(configDir: string): Promise<boolean> {
  const entry = (await cache.get('ai-setup-ran')) as AiFlagCacheEntry | undefined;
  if (!entry?.configDir) {
    return false;
  }
  return entry.configDir === resolve(configDir);
}

